import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.CHeM0PsO.js";const b=JSON.parse('{"title":"ADR 0003 — Cookie-in-WebView auth, not OAuth, for v1","description":"","frontmatter":{"status":"Accepted","date":"2026-07-31T00:00:00.000Z","deciders":"kasunben","sourceUrl":"https://github.com/sovereignfs/sovereign-mobile/blob/main/docs/adrs/0003-cookie-in-webview-auth.md"},"headers":[],"relativePath":"apps/mobile/adrs/0003-cookie-in-webview-auth.md","filePath":"apps/mobile/adrs/0003-cookie-in-webview-auth.md"}'),s={name:"apps/mobile/adrs/0003-cookie-in-webview-auth.md"};function n(r,e,l,c,h,d){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0003-—-cookie-in-webview-auth-not-oauth-for-v1" tabindex="-1">ADR 0003 — Cookie-in-WebView auth, not OAuth, for v1 <a class="header-anchor" href="#adr-0003-—-cookie-in-webview-auth-not-oauth-for-v1" aria-label="Permalink to &quot;ADR 0003 — Cookie-in-WebView auth, not OAuth, for v1&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted. Locked by sovereign workstream 0002&#39;s &quot;Decisions locked&quot; table. Revisit once its blocking dependency below clears.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The user&#39;s Sovereign instance already has its own auth (passkeys, TOTP MFA, sessions). The shell needs to authenticate the WebView against that instance without duplicating any of it natively.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>For v1, auth is <strong>cookie-in-WebView</strong>: the user logs into their instance inside the shell&#39;s WebView exactly as they would in a browser, and the resulting session cookie is scoped to that WebView the same way it would be in any browser tab.</p><h2 id="rejected-alternatives" tabindex="-1">Rejected alternatives <a class="header-anchor" href="#rejected-alternatives" aria-label="Permalink to &quot;Rejected alternatives&quot;">​</a></h2><ul><li><strong>OAuth-first.</strong> Blocked on sovereign RFC 0072&#39;s per-instance, admin-only OAuth client registration — a self-hoster would need to register this shell as an OAuth client on their own instance before first login, which is not viable for a v1 onboarding flow. See sovereign workstream 0001 §5 for the full blocking chain.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>No native credential storage or session logic in this repo for v1 — the WebView&#39;s own cookie jar is the only session state.</li><li>WKWebView&#39;s data store can be evicted under storage pressure (see <a href="./../epics/shell.html">epics/shell.md</a> risks) — the user-visible effect is a forced re-login and cold cache, not data loss, since the instance remains the source of truth.</li><li>Revisit this ADR once RFC 0072 ships; do not build OAuth support ahead of that dependency clearing.</li></ul>',11)])])}const p=t(s,[["render",n]]);export{b as __pageData,p as default};
